<?php
declare(strict_types=1);
require_once dirname(__DIR__,2).'/app/helpers/industry-classes.php';
$user=require_role('admin','staf_bkk');industry_require_ready();$id=positive_id($_GET['id']??'');if(!$id){panel_not_found();}
try{$class=industry_find($id);}catch(InvalidArgumentException){panel_not_found();}
$speakers=panel_query('SELECT s.nama,s.instansi FROM speakers s JOIN industry_class_speakers r ON r.speaker_id=s.id WHERE r.class_id=:id ORDER BY s.nama,s.id',['id'=>$id])->fetchAll();$names=implode(', ',array_column($speakers,'nama'));
$meetings=panel_query('SELECT a.*,s.nama AS pemateri_nama FROM industry_class_meetings a LEFT JOIN speakers s ON s.id=a.pemateri_id WHERE a.class_id=:id ORDER BY a.urutan,a.id',['id'=>$id])->fetchAll();$completed=count(array_filter($meetings,static fn($row)=>$row['status']==='terlaksana'));
$participantTotal=(int)panel_query('SELECT COUNT(*) FROM industry_class_participants WHERE class_id=:id',['id'=>$id])->fetchColumn();$pages=max(1,(int)ceil($participantTotal/50));$page=min($pages,positive_id($_GET['page']??'1')??1);
$participants=panel_query('SELECT s.nis,s.nama,s.kelas,s.jurusan FROM siswa s JOIN industry_class_participants r ON r.siswa_id=s.id WHERE r.class_id=:id ORDER BY s.nama,s.id LIMIT :limit OFFSET :offset',['id'=>$id,'limit'=>50,'offset'=>($page-1)*50])->fetchAll();
panel_start($user,'Kelas Industri — '.$class['nama'],'kelas-industri');
?>
<div class="industry-list-workspace industry-detail-workspace">
<div class="page-actions industry-list-header"><div><h1><?= panel_icon('program') ?> <?= e($class['nama']) ?></h1><p>Informasi kelas, progres pelaksanaan, dan jadwal pertemuan.</p></div><div class="industry-header-actions"><a class="button industry-description" href="<?= e(base_url('panel/kelas-industri/')) ?>"><?= panel_icon('back') ?> Daftar kelas</a><a class="button industry-add" href="<?= e(base_url('panel/kelas-industri/form.php?id='.$id)) ?>"><?= panel_icon('edit') ?> Edit kelas / peserta</a><a class="button industry-description" href="<?= e(base_url('panel/kelas-industri/unduh.php?id='.$id)) ?>"><?= panel_icon('download') ?> Rekap Excel</a></div></div>
<section class="card industry-class-overview" aria-labelledby="class-overview-title">
<div class="industry-class-progress"><h2 id="class-overview-title"><?= panel_icon('tracer') ?> Progres pertemuan</h2><p class="industry-progress-number"><?= $completed ?><span> / <?= (int)$class['rencana_pertemuan'] ?></span></p><p class="industry-detail-muted">pertemuan terlaksana</p><div class="industry-meeting-progress"><progress value="<?= $completed ?>" max="<?= (int)$class['rencana_pertemuan'] ?>" aria-label="<?= $completed ?> dari <?= (int)$class['rencana_pertemuan'] ?> pertemuan terlaksana"></progress></div><span class="industry-status-badge <?= $class['status']==='aktif'?'is-active':'is-archived' ?>"><?= panel_icon($class['status']==='aktif'?'check-circle':'capaian') ?> Kelas <?= e(ucfirst($class['status'])) ?></span></div>
<dl class="industry-class-facts"><div><dt><?= panel_icon('mitra') ?> Mitra industri</dt><dd><?= e($class['mitra_nama']) ?></dd></div><div><dt><?= panel_icon('pemateri') ?> Pemateri kelas</dt><dd><?= e($names?:'Belum ada pemateri') ?></dd></div><div><dt><?= panel_icon('program') ?> Kelas sasaran</dt><dd><?= e($class['kelas_sasaran']?:'Mengikuti peserta yang dipilih') ?></dd></div><div><dt><?= panel_icon('peserta') ?> Peserta terdaftar</dt><dd><?= $participantTotal ?> siswa <a href="#class-participants">Lihat daftar</a></dd></div></dl>
<?php if(trim($class['catatan'])!==''): ?><details class="industry-class-note"><summary><?= panel_icon('message') ?> Catatan kelas</summary><p tabindex="0"><?= nl2br(e($class['catatan'])) ?></p></details><?php endif; ?>
</section>
<section class="card industry-detail-section" aria-labelledby="class-meetings-title"><div class="industry-section-heading"><h2 id="class-meetings-title"><?= panel_icon('calendar') ?> Jadwal pertemuan</h2><span><?= count($meetings) ?> pertemuan direncanakan</span></div><p class="industry-section-help">Gunakan <strong>Atur jadwal</strong> untuk mengisi tanggal, lokasi, pemateri, dan status. Hanya status Terlaksana menambah progres.</p>
<div class="table-scroll panel-sheet industry-class-sheet industry-meeting-sheet" tabindex="0" role="region" aria-label="Jadwal pertemuan, gulir untuk melihat baris dan kolom lainnya"><table><thead><tr><th>Pertemuan</th><th>Tanggal / jam WIB</th><th>Lokasi</th><th>Pemateri</th><th>Materi / catatan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php foreach($meetings as $meeting): ?><tr><td><strong>Pertemuan <?= (int)$meeting['urutan'] ?></strong></td><td><?= e($meeting['tanggal']?:'Belum dijadwalkan') ?><?php if($meeting['jam']): ?><small class="industry-meeting-time"><?= e(substr($meeting['jam'],0,5)) ?> WIB</small><?php endif; ?></td><td><?= e($meeting['lokasi']?:'Belum diisi') ?></td><td><?= e($meeting['pemateri_nama']?:($names?:'Belum ditentukan')) ?></td><td><div class="industry-meeting-notes" tabindex="0"><?= nl2br(e($meeting['materi']?:'Materi belum diisi')) ?><?php if($meeting['catatan']!==''): ?><p><?= nl2br(e($meeting['catatan'])) ?></p><?php endif; ?></div></td><td><span class="industry-status-badge meeting-state-<?= e($meeting['status']) ?>"><?= e(industry_meeting_statuses()[$meeting['status']]) ?></span></td><td><div class="industry-row-actions"><a class="industry-schedule" href="<?= e(base_url('panel/kelas-industri/pertemuan.php?class_id='.$id.'&id='.$meeting['id'])) ?>"><?= panel_icon('edit') ?> Atur jadwal</a></div></td></tr><?php endforeach; ?><?php if(!$meetings): ?><tr><td colspan="7">Belum ada pertemuan. Periksa rencana pertemuan melalui Edit kelas.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="card industry-detail-section" id="class-participants" aria-labelledby="class-participants-title"><div class="industry-section-heading"><h2 id="class-participants-title"><?= panel_icon('peserta') ?> Peserta terdaftar</h2><span><?= $participantTotal ?> siswa</span></div>
<div class="table-scroll panel-sheet industry-class-sheet industry-participant-sheet" tabindex="0" role="region" aria-label="Peserta kelas industri, gulir untuk melihat baris dan kolom lainnya"><table><thead><tr><th>Nama siswa</th><th>Kelas</th><th>Jurusan</th></tr></thead><tbody><?php foreach($participants as $participant): ?><tr><?php foreach(['nama','kelas','jurusan'] as $key): ?><td><?= e($participant[$key]) ?></td><?php endforeach; ?></tr><?php endforeach; ?><?php if(!$participants): ?><tr><td colspan="3">Belum ada siswa yang dipilih satu per satu.<?php if($class['kelas_sasaran']!==''): ?> Sasaran kelas: <?= e($class['kelas_sasaran']) ?>.<?php endif; ?> Pilih siswa melalui Edit kelas / peserta.</td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1): ?><nav class="pagination" aria-label="Halaman peserta kelas industri"><?php foreach(['Sebelumnya'=>$page-1,'Berikutnya'=>$page+1] as $label=>$target):if($target<1||$target>$pages){continue;} ?><a href="<?= e(base_url('panel/kelas-industri/detail.php?id='.$id.'&page='.$target.'#class-participants')) ?>"><?= $label ?></a><?php endforeach; ?><span>Halaman <?= $page ?> dari <?= $pages ?></span></nav><?php endif; ?></section>
</div>
<?php panel_end($user); ?>
